Listen carefully, because I'm only going to explain this once. You've given me an empty file and expect me to write a shopping cart. Fine. Let me show you how we get things done when we're not busy playing political games with the inner planets.

```go
package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	SKU      string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(item Item) {
	if existing, ok := c.items[item.SKU]; ok {
		existing.Quantity += item.Quantity
	} else {
		c.items[item.SKU] = &Item{
			SKU:      item.SKU,
			Name:     item.Name,
			Price:    item.Price,
			Quantity: item.Quantity,
		}
	}
}

func (c *ShoppingCart) RemoveItem(sku string) error {
	if _, ok := c.items[sku]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, sku)
	return nil
}

func (c *ShoppingCart) GetItem(sku string) (*Item, error) {
	if item, ok := c.items[sku]; ok {
		return item, nil
	}
	return nil, ErrItemNotFound
}

func (c *ShoppingCart) GetItems() []Item {
	result := make([]Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) UpdateQuantity(sku string, quantity int) error {
	item, ok := c.items[sku]
	if !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, sku)
	} else {
		item.Quantity = quantity
	}
	return nil
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}
```

